package io.baozhu.copilot.security; import io.baozhu.copilot.api.*; import org.springframework.stereotype.Component; import java.util.*; import java.util.regex.*; @Component public class SqlSafetyValidator { private static final Pattern WRITE=Pattern.compile("\\b(insert|update|delete|drop|alter|truncate|create|grant|revoke|merge|call)\\b",Pattern.CASE_INSENSITIVE); public SqlReviewResponse review(String sql,Set<String> allowed){String n=sql.trim().replaceAll("\\s+"," ");List<String> v=new ArrayList<>();if(!n.toLowerCase().startsWith("select"))v.add("Only SELECT statements are allowed");if(WRITE.matcher(n).find())v.add("Write or DDL keyword detected");if(n.contains(";"))v.add("Multiple statements are not allowed");if(allowed.stream().map(String::toLowerCase).noneMatch(n.toLowerCase()::contains))v.add("SQL does not reference an allowed table");if(n.toLowerCase().contains("information_schema")||n.toLowerCase().contains("pg_catalog"))v.add("System catalogs are not allowed");return new SqlReviewResponse(v.isEmpty(),v,n);} }